visual.source:
flowchart TB
  subgraph G4["4 失敗したプロセス"]
    AS@{ svc: "Amazon EC2 Auto Scaling", label: "EC2 Auto Scaling" }
    EC@{ svc: "Amazon ECS", label: "Amazon ECS<br/>と Amazon EKS" }
  end
  subgraph G3["3 失敗したデプロイ"]
    CF@{ svc: "AWS CloudFormation", label: "CloudFormation" }
    CP@{ svc: "AWS CodePipeline", label: "CodePipeline<br/>と CodeDeploy" }
  end
  subgraph G2["2 原因を探る"]
    XR["AWS X-Ray<br/>と canary"]
  end
  subgraph G1["1 健全性を知る"]
    HE@{ svc: "AWS Health", label: "AWS Health" }
    OC@{ svc: "AWS Systems Manager", label: "OpsCenter" }
  end

flowchart TB
  R["自分のリソースの性能<br/>サービスとアカウントの可用性"]
  HE@{ svc: "AWS Health", label: "AWS Health<br/>警告と通知" }
  EB@{ svc: "Amazon EventBridge", label: "Amazon EventBridge<br/>追加料金なし" }
  R -- "健全性の変化" --> HE
  HE -- "イベントを受ける" --> EB

flowchart TB
  subgraph K["OpsItem を作るきっかけ"]
    CW@{ svc: "Amazon CloudWatch", label: "CloudWatch<br/>のアラーム<br/>ALARM<br/>（アラーム状態）" }
    EB@{ svc: "Amazon EventBridge", label: "EventBridge<br/>サービスのイベント" }
  end
  subgraph S["調べる情報を集める元"]
    CFG@{ svc: "AWS Config", label: "AWS Config<br/>構成の記録" }
    CT@{ svc: "AWS CloudTrail", label: "CloudTrail のログ<br/>操作の記録" }
    CE["CloudWatch Events"]
  end
  OC@{ svc: "AWS Systems Manager", label: "OpsCenter<br/>OpsItem" }
  CW -- "設定すれば自動で" --> OC
  EB --> OC
  CFG -- "情報を集める" --> OC
  CT --> OC
  CE --> OC

flowchart TB
  TP@{ svc: "AWS CloudFormation", label: "CloudFormation<br/>テンプレートで設定" }
  EC@{ svc: "Amazon EC2", label: "EC2 インスタンス<br/>cloud-init と cfn のログ" }
  CW@{ svc: "Amazon CloudWatch", label: "CloudWatch<br/>コンソールに表示" }
  TP -. "ログを出す設定" .-> EC
  EC -- "ログを出す" --> CW

flowchart TB
  subgraph G4["4 失敗したプロセス"]
    AS@{ svc: "Amazon EC2 Auto Scaling", label: "EC2 Auto Scaling<br/>unhealthy を置き換え" }
    EC@{ svc: "Amazon ECS", label: "ECS のタスクのエラー<br/>EKS のエラーコード" }
  end
  subgraph G3["3 失敗したデプロイ"]
    CF@{ svc: "AWS CloudFormation", label: "CloudFormation<br/>根本原因のイベント" }
    CP@{ svc: "AWS CodePipeline", label: "CodePipeline の再試行<br/>CodeDeploy のログ" }
  end
  subgraph G2["2 原因を探る"]
    XR["AWS X-Ray<br/>trace map と<br/>X-Ray Analytics"]
  end
  subgraph G1["1 健全性を知る"]
    HE@{ svc: "AWS Health", label: "AWS Health<br/>EventBridge で受信" }
    OC@{ svc: "AWS Systems Manager", label: "OpsCenter<br/>OpsItem と情報の集約" }
  end
